 *  steward may open a claim of theirs then.
 *  `approver` is the user who may approve or reject their PENDING claims as a steward may (null when none). */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: Grades;
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retired: boolean;
  retiredFrom: string | null;
  retiredNow: boolean;
  held: boolean;
  holds: Hold[];
  patronIds: number[];
  terms: number | null;
  contact: string | null;
  aliases: string[];
  clashing: boolean;
  origin: string | null;
  pastRetirements: PastRetirement[];
  tags: string[];
  snapshots: Snapshot[];
  statements: StatementLine[];
  flag: string | null;
  approver: string | null;
};

/** A statement: its date (yyyy-MM-dd) and the person's due-total it recorded (two decimals, or n/a). */

